    let atlasStatsChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.webm_texture.WebmTextureHostApi.atlasStats\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      atlasStatsChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let atlasIdArg = args[0] as! Int64
        do {
          let result = try api.atlasStats(atlasId: atlasIdArg)
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      atlasStatsChannel.setMessageHandler(nil)
    }
    /// Frees the atlas. Animations still in it are left without a texture
    /// until [detachFromAtlas] (or [dispose]). Its page textures are retired,
    /// as listed in the result.
    let disposeAtlasChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.webm_texture.WebmTextureHostApi.disposeAtlas\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      disposeAtlasChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let atlasIdArg = args[0] as! Int64
        do {
          let result = try api.disposeAtlas(atlasId: atlasIdArg)
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      disposeAtlasChannel.setMessageHandler(nil)
    }
    /// Sets the directory for the frame cache and returns the one in use, an
    /// absolute path. With a null [directory] nothing changes: the result is
    /// the current one, which starts as `webm_texture` under the app's cache
    /// directory (`Context.cacheDir` on Android, `Library/Caches` on iOS).
    ///
    /// The directory is created when the first animation needs it, and only
    /// ever holds files the core wrote (`*.wsc`). Animations created
    /// afterwards cache there; existing ones keep their files. Cache
    /// administration (`wt_cache_*`) runs over FFI, so Dart passes this path to
    /// it.
    let configureCacheChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.webm_texture.WebmTextureHostApi.configureCache\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      configureCacheChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let directoryArg: String? = nilOrValue(args[0])
        do {
          let result = try api.configureCache(directory: directoryArg)
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      configureCacheChannel.setMessageHandler(nil)
    }
  }
}

private class PigeonStreamHandler<ReturnType>: NSObject, FlutterStreamHandler {
  private let wrapper: PigeonEventChannelWrapper<ReturnType>
  private var pigeonSink: PigeonEventSink<ReturnType>? = nil

  init(wrapper: PigeonEventChannelWrapper<ReturnType>) {
    self.wrapper = wrapper
  }

  func onListen(withArguments arguments: Any?, eventSink events: @escaping FlutterEventSink)
    -> FlutterError?
  {
    pigeonSink = PigeonEventSink<ReturnType>(events)
    wrapper.onListen(withArguments: arguments, sink: pigeonSink!)
    return nil
  }

  func onCancel(withArguments arguments: Any?) -> FlutterError? {
    pigeonSink = nil
    wrapper.onCancel(withArguments: arguments)
    return nil
  }
}

class PigeonEventChannelWrapper<ReturnType> {
  func onListen(withArguments arguments: Any?, sink: PigeonEventSink<ReturnType>) {}
  func onCancel(withArguments arguments: Any?) {}
}

class PigeonEventSink<ReturnType> {
  private let sink: FlutterEventSink

  init(_ sink: @escaping FlutterEventSink) {
    self.sink = sink
  }

  func success(_ value: ReturnType) {
    sink(value)
  }

  func error(code: String, message: String?, details: Any?) {
    sink(FlutterError(code: code, message: message, details: details))
  }

  func endOfStream() {
    sink(FlutterEndOfEventStream)
  }

}

/// Errors that happen after `createAnimation` returned, such as a lost
/// surface or a decode failure mid-playback.
/// A typed channel for communicating with the Flutter application using asynchronous event streams.
class StreamErrorsEventChannel {
  private let channel: FlutterEventChannel

  init(messenger: FlutterBinaryMessenger, instanceName: String = "") {
    var channelName = "dev.flutter.pigeon.webm_texture.WebmTextureEvents.streamErrors"
    if !instanceName.isEmpty {
      channelName += ".\(instanceName)"
    }
    channel = FlutterEventChannel(name: channelName, binaryMessenger: messenger, codec: messagesPigeonMethodCodec)
  }

  /// Sets the stream handler for this channel, replacing any previous handler.
  /// 
  /// Pass `nil` to remove the event channel registration.
  func setStreamHandler(_ streamHandler: StreamErrorsStreamHandler?) {
    let internalHandler = streamHandler.map({ PigeonStreamHandler<AnimationErrorMessage>(wrapper: $0) })
    channel.setStreamHandler(internalHandler)
  }
}

class StreamErrorsStreamHandler: PigeonEventChannelWrapper<AnimationErrorMessage> {
  /// Creates and returns a new event channel that calls the provided stream handler.
  /// 
  /// The returned channel can be stored to allow changing or removing the stream handler.
  /// If the handler will not be changed for the lifetime of the engine associated with the messenger,
  /// the return value can be ignored.
  @discardableResult static func register(
    with messenger: FlutterBinaryMessenger,
    instanceName: String = "",
    streamHandler: StreamErrorsStreamHandler
  ) -> StreamErrorsEventChannel {
    let channel = StreamErrorsEventChannel(messenger: messenger, instanceName: instanceName)
    channel.setStreamHandler(streamHandler)
    return channel
  }
}
      
